def break_even(api_cost_per_task, gpu_hourly, tasks_per_hour, max_util=0.7, hours=730):
    if gpu_hourly / (tasks_per_hour * max_util) >= api_cost_per_task:
        return None
    return gpu_hourly * hours / api_cost_per_task

