import math

def dpo_pair_loss(pc, pr, rc, rr, beta=0.1):
    # pc, pr: policy log-probs of chosen and rejected; rc, rr: reference log-probs
    margin = beta * ((pc - rc) - (pr - rr))
    return math.log1p(math.exp(-margin))
